-- Üretildi: npm run config:sql (src/config/economy.json ve src/config/items.json). Elle değiştirme;
-- JSON'ları düzenleyip komutu yeniden çalıştır, sonra bu dosyayı Supabase SQL Editor'de çalıştır.

values (1, $cfg${"session":{"beatSeconds":60,"graceSeconds":90,"idleMinutes":15,"idleAnswerSeconds":60,"maxMinutes":300,"noteMin":3,"noteMax":200,"wiltMinutes":5},"elmas":{"study":{"tiers":[{"upTo":60,"minutesPer":10},{"upTo":120,"minutesPer":20},{"upTo":180,"minutesPer":30}],"dailyCap":12},"streak":{"minMinutes":20,"tiers":[{"days":3,"bonus":1},{"days":7,"bonus":2},{"days":14,"bonus":3},{"days":30,"bonus":4}]},"reflection":{"bonus":1,"minNote":10},"plan":3,"book":{"bonus":5,"perWeek":2},"giftMax":50,"quests":[{"id":"day30","scope":"day","title":"Bugün 30 dk çalış","icon":"⏱️","target":30,"reward":2},{"id":"week5days","scope":"week","title":"Bu hafta 5 gün çalış","icon":"📅","target":5,"reward":5},{"id":"week3plans","scope":"week","title":"Bu hafta 3 günün planını bitir","icon":"📋","target":3,"reward":5},{"id":"week3courses","scope":"week","title":"Bu hafta 3 farklı derse çalış","icon":"🎨","target":3,"reward":3},{"id":"weekBook","scope":"week","title":"Bu hafta bir kitap bitir","icon":"📚","target":1,"reward":5}]},"chest":{"days":5,"minutes":150},"freeze":{"max":2,"coverDays":7},"stars":{"perDay":8},"levelHours":[0,5,15,30,60,100,150],"skillTierMinutes":[120,360,900]}$cfg$::jsonb, now())
on conflict (id) do update set value = excluded.value, updated_at = now();

delete from public.item_defs where id not in ('char:female-b', 'char:female-c', 'char:female-f', 'char:male-a', 'char:male-e', 'char:male-f', 'char:female-e', 'char:female-a', 'char:male-c', 'char:female-d', 'char:male-d', 'char:male-b', 'acc:glasses', 'acc:sunglasses', 'acc:crown', 'pet:cat', 'pet:dog', 'pet:pig', 'pet:beaver', 'pet:koala', 'pet:panda', 'pet:penguin', 'pet:parrot', 'pet:monkey', 'pet:polar', 'pet:tiger', 'pet:lion', 'pet:giraffe', 'pet:elephant', 'yapi:sign', 'yapi:pot', 'yapi:campfire', 'yapi:tent', 'yapi:canoe', 'yapi:bed', 'yapi:bridge', 'yapi:bigtent', 'yapi:column', 'yapi:statue', 'yapi:ring', 'yapi:obelisk', 'sus:flowerY', 'sus:flowerP', 'sus:path', 'sus:pathWood', 'sus:mushroom', 'sus:smallpot', 'sus:fence', 'sus:fencePlanks', 'sus:platform', 'freeze');

on conflict (id) do update set
  category = excluded.category, price = excluded.price, repeat = excluded.repeat, in_chest = excluded.in_chest,
  w = excluded.w, h = excluded.h, rotations = excluded.rotations, placement = excluded.placement, def = excluded.def;
